"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["1381"],{69263(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_divulgacao.justificativa_caractere_invalido","status":422,"titulo":"A justificativa cont\xe9m o caractere nulo, de controle ou de formata\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.configuracao_divulgacao.justificativa_caractere_invalido","requisitos":[],"oQueAconteceu":["A justificativa da divulga\xe7\xe3o p\xfablica cont\xe9m o caractere nulo (U+0000), um caractere de controle (fora a quebra de linha, o retorno de carro e a tabula\xe7\xe3o) ou de formata\xe7\xe3o, ou texto que n\xe3o \xe9 Unicode v\xe1lido. Esses caracteres s\xe3o invis\xedveis e n\xe3o s\xe3o tratados\\ncomo espa\xe7o em branco, por isso n\xe3o s\xe3o removidos na normaliza\xe7\xe3o do texto, e o sistema n\xe3o os aceita. A quebra\\nde linha, o retorno de carro e a tabula\xe7\xe3o s\xe3o aceitos, porque a justificativa \xe9 um texto de v\xe1rias linhas.","A confer\xeancia vale para qualquer justificativa enviada, mesmo quando o `NOME` n\xe3o est\xe1 na lista.\\nA recusa vem junto das demais viola\xe7\xf5es do mesmo pedido, no array `errors[]`, e pode aparecer ao\\nlado de\\n[`justificativa_muito_longa`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_muito_longa),\\nde\\n[`campos_publicos_vazio`](/erros/uniplus.selecao.configuracao_divulgacao.campos_publicos_vazio), de\\n[`campo_nao_permitido`](/erros/uniplus.selecao.configuracao_divulgacao.campo_nao_permitido), de\\n[`numero_inscricao_obrigatorio`](/erros/uniplus.selecao.configuracao_divulgacao.numero_inscricao_obrigatorio)\\ne de\\n[`formas_de_identificacao_excludentes`](/erros/uniplus.selecao.configuracao_divulgacao.formas_de_identificacao_excludentes).\\nN\xe3o vem junto de\\n[`justificativa_obrigatoria`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_obrigatoria),\\nque exige a justificativa ausente.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz esses caracteres, porque a\\ndefini\xe7\xe3o o recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o \xfanica, sem a lista\\n`errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Remova o caractere inv\xe1lido da justificativa, por exemplo digitando o texto de novo em vez de col\xe1-lo,\\ne reenvie. Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de\\nreenviar.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a divulga\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o da divulga\xe7\xe3o p\xfablica do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao divulgacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);